from test_bufftap import test

setup="""
local B=BuffTap
B.db.campReminder=true; B.db.campAnywhere=false; B.db.campTrackBag=false
C_UnitAuras.GetPlayerAuraBySpellID=function(id) return playerAuras[id] end
function campAura(id,remaining,duration) playerAuras[id]={spellId=id,expirationTime=remaining and now+remaining or 0,duration=duration or 0} end
"""
bagsetup=setup+"""
items[279981]={name='Basic Campfire Kit',icon=135805,usable=true,spell=1307227}; bags[279981]=2
slotItem=279981
C_Container.GetContainerItemInfo=function(b,s) if b==0 and s==1 and slotItem then return {itemID=slotItem,isLocked=false} end end
C_Container.GetContainerItemCooldown=function() return 0,0,1 end
"""

test('Camping defaults off with no idle timers',"assert(not BuffTap.db.campReminder and BuffTap.db.campAnywhere); local n=liveTimers(); for i=1,100 do BuffTap.campingEvents.scripts.OnEvent(nil,'UNIT_AURA','player') end; assert(liveTimers()==n and not BuffTap.campReminderIcon)")
test('Camp missing away does not nag by default',setup+"B:UpdateCamping(); assert(not B.campReminderIcon)")
test('Camp proximity offers a separate reminder without changing buff action',setup+"local id=B.action.id; campAura(1283391); B:UpdateCamping(); assert(B.campReminderIcon.shown and B.action.id==id and bindings.MOUSEWHEELDOWN)")
test('Camp healthy benefits hide the reminder and schedule warning',setup+"campAura(1283391); campAura(1229741,3600,3600); B:UpdateCamping(); assert(not B.campReminderIcon and B.timers.camp.due>now+3200)")
test('Camp warning wakes once at threshold',setup+"campAura(1283391); campAura(1229741,310,3600); B:UpdateCamping(); advance(11); assert(B.campReminderIcon.shown)")
test('Camp optional away reminder works',setup+"B.db.campAnywhere=true; B:UpdateCamping(); assert(B.campReminderIcon.shown)")
test('Camp direct aura refusal is unknown rather than missing',setup+"B.db.campAnywhere=true; C_UnitAuras.GetPlayerAuraBySpellID=function() error('restricted') end; B:UpdateCamping(); assert(B:CampingState().unknown and not B.campReminderIcon)")
test('Camp secret expiry cannot be compared',setup+"B.db.campAnywhere=true; playerAuras[1229741]={expirationTime={secret=true}}; B:UpdateCamping(); assert(B:CampingState().unknown and not B.campReminderIcon)")
test('Camp global aura restriction suppresses reminder',setup+"B.db.campAnywhere=true; C_Secrets={ShouldAurasBeSecret=function() return true end}; B:UpdateCamping(); assert(not B.campReminderIcon)")
test('Camp reminder does not show dead mounted or instanced',setup+"B.db.campAnywhere=true; dead=true; B:UpdateCamping(); assert(not B.campReminderIcon); dead=false; mounted=true; B:UpdateCamping(); assert(not B.campReminderIcon); mounted=false; IsInInstance=function() return true,'party' end; B:UpdateCamping(); assert(not B.campReminderIcon)")
test('Camp snooze lasts independently of aura events',setup+"campAura(1283391); B:SnoozeCamping(600); for i=1,25 do B.campingEvents.scripts.OnEvent(nil,'UNIT_AURA','player') end; advance(.2); assert(not B.campReminderIcon); advance(600); assert(B.campReminderIcon.shown)")
test('Camp session snooze does not affect normal buffing',setup+"campAura(1283391); local id=B.action.id; B:SnoozeCamping(0); B:UpdateCamping(); assert(not B.campReminderIcon and B.action.id==id)")
test('Camp right click opens snooze menu on its first click',setup+"campAura(1283391); B:UpdateCamping(); B.campReminderIcon.scripts.OnClick(B.campReminderIcon,'RightButton'); assert(B.campSnoozeMenu.shown)")
test('Camp waiting uses either confirmed waiting aura',setup+"campAura(1289723,45,60); local s=B:CampingState(); assert(s.waiting==45 and s.waitDuration==60); B:UpdateCamping(); assert(B.campReminderIcon.shown and B.timers.camp.due==now+1)")
test('Camp older waiting aura is supported',setup+"campAura(1229739,20,60); assert(B:CampingState().waiting==20)")
test('Camp waiting cannot claim benefits until actual benefit aura',setup+"campAura(1283391); campAura(1289723,1,60); B:UpdateCamping(); advance(2); assert(not B:CampingState().active and B.campReminderIcon.shown)")
test('Camp combat cancels its timer without protected writes',bagsetup+"B:ToggleCampTray(); combat=true; B.campingEvents.scripts.OnEvent(nil,'PLAYER_REGEN_DISABLED'); assert(not B.timers.camp); B:PrepareCampButton(B.campTray.rows[1]); B:ToggleCampTray()")
test('Camp setup can be opened while reminders disabled',bagsetup+"B.db.campReminder=false; B:ToggleCampTray(); assert(B.campTray.shown and #B.campTray.rows==1 and not B.campReminderIcon)")
test('Camp close stays closed after scans',bagsetup+"B:ToggleCampTray(); B.campTray:Hide(); B:UpdateCamping(); assert(not B.campTray.shown and not B.campTrayOpen)")
test('Camp bag slot is used rather than item-id casting',bagsetup+"B:ToggleCampTray(); local r=B.campTray.rows[1]; r.scripts.PreClick(r,'LeftButton',false); assert(r.attrs.type1=='item' and r.attrs.item=='0 1')")
test('Camp fresh click refuses recycled bag slot',bagsetup+"B:ToggleCampTray(); local r=B.campTray.rows[1]; slotItem=999; r.scripts.PreClick(r,'LeftButton',false); assert(not r.attrs.type1 and not r.attrs.item)")
test('Camp fresh click refuses newly active cooldown',bagsetup+"B:ToggleCampTray(); local r=B.campTray.rows[1]; C_Container.GetContainerItemCooldown=function() return now,3600,1 end; r.scripts.PreClick(r,'LeftButton',false); assert(not r.attrs.type1)")
test('Camp unknown cooldown fails closed',bagsetup+"B:ToggleCampTray(); local r=B.campTray.rows[1]; C_Container.GetContainerItemCooldown=function() return {secret=true},3600,1 end; r.scripts.PreClick(r,'LeftButton',false); assert(not r.attrs.type1)")
test('Camp unusable item fails closed',bagsetup+"B:ToggleCampTray(); local r=B.campTray.rows[1]; items[279981].usable=false; r.scripts.PreClick(r,'LeftButton',false); assert(not r.attrs.type1)")
test('Camp features require current proximity unlike campfires',bagsetup+"slotItem=279956; bags[279981]=0; bags[279956]=1; items[279956]={name='Mana Well',usable=true,spell=1307259}; B:ToggleCampTray(); local r=B.campTray.rows[1]; assert(not r.attrs.type1); campAura(1283391); r.scripts.PreClick(r,'LeftButton',false); assert(r.attrs.type1=='item'); playerAuras={}; r.scripts.PreClick(r,'LeftButton',false); assert(not r.attrs.type1)")
test('Camp global disable clears armed item at click',bagsetup+"B:ToggleCampTray(); local r=B.campTray.rows[1]; B.db.enabled=false; r.scripts.PreClick(r,'LeftButton',false); assert(not r.attrs.type1)")
test('Camp row state driver clears payload in combat',bagsetup+"B:ToggleCampTray(); local r=B.campTray.rows[1]; r.secure=true; combat=true; assert(loadstring('local self,newstate=...; '..r.attrs['_onstate-campsafety']))(r,'blocked'); assert(not r.attrs.type1 and not r.shown)")
test('Camp parent state driver hides window in combat',bagsetup+"B:ToggleCampTray(); local r=B.campTray; r.secure=true; combat=true; assert(loadstring('local self,newstate=...; '..r.attrs['_onstate-campsafety']))(r,'blocked'); assert(not r.shown and not B.campTrayOpen)")
test('Camp recipe discovery does not infer learned from skill',setup+"GetProfessions=function() return 1 end; GetProfessionInfo=function() return 'Cooking',1,300,300,0,0,185 end; local e=B:CampingEntries(); assert(#e>=1 and not e[1].learned)")
test('Camp opens profession on first click and crafts on second only',setup+"local open=0; local crafts=0; C_TradeSkillUI={GetBaseProfessionInfo=function() return {professionID=open} end,OpenTradeSkill=function(id) open=id end,GetRecipeInfo=function() return {learned=true,numAvailable=2} end,CraftRecipe=function(id,n) assert(n==1); crafts=crafts+1 end}; local e=B.CampingItems[1]; assert(not B:CraftCampEntry(e) and open==185 and crafts==0); assert(B:CraftCampEntry(e) and crafts==1)")
test('Camp refuses unlearned recipe and insufficient materials',setup+"local crafts=0; C_TradeSkillUI={GetBaseProfessionInfo=function() return {professionID=185} end,GetRecipeInfo=function() return {learned=false,numAvailable=2} end,CraftRecipe=function() crafts=crafts+1 end}; assert(not B:CraftCampEntry(B.CampingItems[1])); C_TradeSkillUI.GetRecipeInfo=function() return {learned=true,numAvailable=0} end; assert(not B:CraftCampEntry(B.CampingItems[1]) and crafts==0)")
test('Camp recipe never crafts automatically on trade skill event',setup+"local n=0; B.campTrayOpen=true; C_TradeSkillUI={CraftRecipe=function() n=n+1 end}; B.campingEvents.scripts.OnEvent(nil,'TRADE_SKILL_LIST_UPDATE'); advance(.2); assert(n==0)")
test('Camp detects all 39 verified recipes including top-tier alchemy',"assert(#BuffTap.CampingItems==39); local found=false; for _,e in ipairs(BuffTap.CampingItems) do if e.item==279990 then found=e.recipe==1263078 and e.use==1307172 end end; assert(found)")
test('Camp repeated aura events keep one replaceable timer',setup+"campAura(1283391); for i=1,500 do B.campingEvents.scripts.OnEvent(nil,'UNIT_AURA','player') end; assert(liveTimers()==1); advance(.2); assert(B.campReminderIcon.shown)")
test('Camp prefixed command opens tray',bagsetup+"SlashCmdList.BUFFTAP('camp'); assert(B.campTray.shown)")
test('Camp standalone command opens tray',bagsetup+"SlashCmdList.BUFFTAPCAMP(); assert(B.campTray.shown)")
test('Icon effect migration preserves old pulse and glow preferences',"BuffTap.db.effectStyle=nil; BuffTap.db.glow=false; BuffTap.db.pulse=false; assert(BuffTap:IconEffectStyle()=='none'); BuffTap.db.glow=true; assert(BuffTap:IconEffectStyle()=='soft'); BuffTap.db.pulse=true; assert(BuffTap:IconEffectStyle()=='pulse')")
test('Icon effects unsupported clients retain soft glow',"BuffTap.db.effectStyle='pixel'; BuffTap:ApplyIconEffect(BuffTap.button,true); assert(BuffTap.button.glow.shown)")
test('Icon hidden reminder stops effect and preserves binding',"BuffTap.db.effectStyle='pixel'; BuffTap:ApplyIconEffect(BuffTap.button,true); BuffTap.db.showReminder=false; BuffTap:UpdatePulse(); assert(not BuffTap.button.glow.shown and bindings.MOUSEWHEELDOWN)")
test('Icon nearby quiet action never runs effect',"BuffTap.db.effectStyle='pixel'; BuffTap.nearbyQuietAction=true; BuffTap:UpdatePulse(); assert(not BuffTap.button.glow.shown)")
test('Icon repeated refresh does not restart allocated effect',"local lib=LibStub:NewLibrary('LibCustomGlow-1.0',999); local starts,stops=0,0; lib.PixelGlow_Start=function() starts=starts+1 end; lib.PixelGlow_Stop=function() stops=stops+1 end; BuffTap.db.effectStyle='pixel'; for i=1,100 do BuffTap:ApplyIconEffect(BuffTap.button,true) end; assert(starts==1); BuffTap:ApplyIconEffect(BuffTap.button,false); assert(stops==1)")
test('Camp and icon preferences copy through standard named profiles',"local B=BuffTap; B.db.effectStyle='pixel'; B.db.effectColor='cyan'; B.db.effectSpeed='fast'; B.db.campReminder=true; B.db.campAnywhere=true; B.db.campWarning=600; B:CreateSettingsProfile('Camping',true); assert(B.db.effectStyle=='pixel' and B.db.effectColor=='cyan' and B.db.campReminder and B.db.campAnywhere and B.db.campWarning==600)")


test('Camp current item spell mismatch prevents use',bagsetup+"B:ToggleCampTray(); local r=B.campTray.rows[1]; items[279981].spell=999; r.scripts.PreClick(r,'LeftButton',false); assert(not r.attrs.type1)")
test('Camp linked profession cannot prove a recipe learned',setup+"GetProfessions=function() return 1 end; GetProfessionInfo=function() return 'Cooking',1,300,300,0,0,185 end; C_TradeSkillUI={IsTradeSkillLinked=function() return true end,GetBaseProfessionInfo=function() return {professionID=185} end,GetRecipeInfo=function() return {learned=true} end}; B:CampingEntries(); assert(not next(B.campLearned))")
test('Camp row does not both place and craft a newly arrived item',bagsetup+"bags[279981]=0; slotItem=nil; GetProfessions=function() return 1 end; GetProfessionInfo=function() return 'Cooking',1,1,300,0,0,185 end; B:ToggleCampTray(); local r=B.campTray.rows[1]; local n=0; B.CraftCampEntry=function() n=n+1 end; bags[279981]=1; slotItem=279981; r.scripts.PreClick(r,'LeftButton',false); r.scripts.PostClick(r,'LeftButton',false); assert(r.attrs.type1=='item' and n==0)")
test('Camp button release is the only actionable edge',bagsetup+"B:ToggleCampTray(); local r=B.campTray.rows[1]; r:SetAttribute('type1',nil); r.scripts.PreClick(r,'LeftButton',true); assert(not r.attrs.type1)")
test('Camp preference corruption normalizes without affecting buffs',"local B=BuffTap; local id=B.action.id; B.db.campWarning=0/0; B.db.campX=math.huge; B.db.campReminder='yes'; B:NormalizeCamping(); assert(B.db.campWarning==300 and B.db.campX==100 and not B.db.campReminder and B.action.id==id)")


test('Camp sounds default off and cannot repeat every scan',setup+"local n=0; B.PlayAlert=function() n=n+1 end; campAura(1283391); for i=1,30 do B:UpdateCamping() end; assert(n==0); B.campAlerted=false; B.db.campSound=true; for i=1,30 do B:UpdateCamping() end; assert(n==1)")
test('Camp snooze popup hides when camp benefits become healthy',setup+"campAura(1283391); B:UpdateCamping(); B.campReminderIcon.scripts.OnClick(B.campReminderIcon,'RightButton'); campAura(1229741,3600,3600); B:UpdateCamping(); assert(not B.campSnoozeMenu.shown)")


test('Camp setup reuses its frames and rows across repeated opens',bagsetup+"local create=CreateFrame; local made=0; CreateFrame=function(...) made=made+1; return create(...) end; B:ToggleCampTray(); local initial=made; for i=1,100 do B:ToggleCampTray(); B:ToggleCampTray() end; assert(made==initial and #B.campTray.rows==1)")
test('Camp maximum carried inventory fits a fixed two-column grid',bagsetup+"local make=CreateFrame; CreateFrame=function(...) local f=make(...); f.SetHeight=function(self,h) self.testHeight=h end; f.SetPoint=function(self,...) self.testPoint={...} end; f.SetSize=function(self,w,h) self.testWidth=w; self.testHeight=h end; return f end; for _,e in ipairs(B.CampingItems) do bags[e.item]=1; items[e.item]={name=e.name,spell=e.use,usable=true} end; B:ToggleCampTray(); local f=B.campTray; assert(#B:CampingEntries()<=14 and f.testHeight<=734); for i,r in ipairs(f.rows) do assert(r.testWidth==190 and r.testHeight==52); assert(r.testPoint[2]==16+((i-1)%2)*198) end")
test('Camp frame is foreground and every secure row belongs to it',bagsetup+"local create=CreateFrame; CreateFrame=function(...) local f=create(...); f.SetFrameStrata=function(self,v) self.testStrata=v end; f.SetToplevel=function(self,v) self.testTop=v end; return f end; B:ToggleCampTray(); assert(B.campTray.testStrata=='FULLSCREEN_DIALOG' and B.campTray.testTop and B.campTray.rows[1].parent==B.campTray)")
test('Camp reminder position is not reset while dragging',setup+"campAura(1283391); B:UpdateCamping(); local icon=B.campReminderIcon; icon.dragging=true; icon.ClearAllPoints=function() error('position reset during drag') end; B:UpdateCamping()")
test('Camp requested item data wakes only its own tray',bagsetup+"local n=liveTimers(); B.campingEvents.scripts.OnEvent(nil,'ITEM_DATA_LOAD_RESULT',999); assert(liveTimers()==n)")
test('Camp temporary snooze and profession cache do not enter profiles',setup+"B.campSnoozeSession=true; B.campLearned={[1229737]=true}; B:CreateSettingsProfile('Camp copy',true); assert(B.db.campSnoozeSession==nil and B.db.campLearned==nil)")
for locale in ['deDE','frFR','esES','ptBR']:
    test('Camp and effect controls are localized '+locale,"assert(BuffTap:Text('Camp setup')~='Camp setup' and BuffTap:Text('Effect: Pixel border')~='Effect: Pixel border')",locale=locale)

test('Legacy glow command still changes an explicitly selected effect',"BuffTap.db.effectStyle='pixel'; BuffTap.db.pulse=false; SlashCmdList.BUFFTAP('glow off'); assert(BuffTap:IconEffectStyle()=='none')")


test('Camp reminders default to away warnings and both components',"local B=BuffTap; assert(B.db.campAnywhere and B.db.campTrackBenefits and B.db.campTrackBag); B.db.campAnywhere=false; B:InitDB(); assert(not B.db.campAnywhere)")
test('Away warning works without any camp proximity aura',setup+"B.db.campAnywhere=true; B:UpdateCamping(); assert(B.campReminderIcon.shown)")
test('Healthy camp does not suppress a missing sleeping bag XP warning',setup+"B.db.campAnywhere=true; B.db.campTrackBag=true; campAura(1229741,3600,3600); B:UpdateCamping(); assert(B.campReminderIcon.shown)")
test('Healthy sleeping bag XP does not suppress missing camp benefits',setup+"B.db.campAnywhere=true; B.db.campTrackBag=true; campAura(429959,3600,7200); playerAuras[429959].applications=3; B:UpdateCamping(); assert(B.campReminderIcon.shown)")
test('Both healthy components hide the reminder',setup+"B.db.campAnywhere=true; B.db.campTrackBag=true; campAura(1229741,3600,3600); campAura(429959,7200,7200); playerAuras[429959].applications=3; B:UpdateCamping(); assert(not B.campReminderIcon)")
test('Sleeping bag warning tracks missing stacks until all three are present',setup+"B.db.campAnywhere=true; B.db.campTrackBenefits=false; B.db.campTrackBag=true; campAura(429959,7200,7200); playerAuras[429959].applications=1; B:UpdateCamping(); assert(B.campReminderIcon.shown); playerAuras[429959].applications=2; B:UpdateCamping(); assert(B.campReminderIcon.shown); playerAuras[429959].applications=3; B:UpdateCamping(); assert(not B.campReminderIcon.shown)")
test('Sleeping bag expiration schedules its own warning',setup+"B.db.campAnywhere=true; B.db.campTrackBenefits=false; B.db.campTrackBag=true; campAura(429959,310,7200); playerAuras[429959].applications=3; B:UpdateCamping(); advance(11); assert(B.campReminderIcon.shown)")
test('Earliest camp or sleeping bag threshold wins',setup+"B.db.campAnywhere=true; B.db.campTrackBag=true; campAura(1229741,2000,3600); campAura(429959,400,7200); playerAuras[429959].applications=3; B:UpdateCamping(); assert(B.timers.camp.due<now+101)")
test('Sleeping bag unknown stacks never mean missing XP',setup+"B.db.campAnywhere=true; B.db.campTrackBenefits=false; B.db.campTrackBag=true; campAura(429959,7200,7200); playerAuras[429959].applications={secret=true}; B:UpdateCamping(); assert(not B.campReminderIcon)")
test('Known missing camp can warn despite unreadable sleeping bag data',setup+"B.db.campAnywhere=true; B.db.campTrackBag=true; local get=C_UnitAuras.GetPlayerAuraBySpellID; C_UnitAuras.GetPlayerAuraBySpellID=function(id) if id==429959 then error('restricted') end; return get(id) end; B:UpdateCamping(); assert(B.campReminderIcon.shown)")
test('Sleeping bag XP can be disabled independently',setup+"B.db.campAnywhere=true; B.db.campTrackBag=false; campAura(1229741,3600,3600); B:UpdateCamping(); assert(not B.campReminderIcon)")
test('Camp benefits can be disabled independently',setup+"B.db.campAnywhere=true; B.db.campTrackBenefits=false; B.db.campTrackBag=true; campAura(429959,7200,7200); playerAuras[429959].applications=3; B:UpdateCamping(); assert(not B.campReminderIcon)")
test('Sleeping bag reminders stop when the player cannot earn XP',setup+"B.db.campAnywhere=true; B.db.campTrackBenefits=false; B.db.campTrackBag=true; UnitXPMax=function() return 0 end; B:UpdateCamping(); assert(not B.campReminderIcon)")
test('Resting tracks the actual sleeping bag aura without inventing progress',setup+"campAura(429960); local state=B:CampingState(); assert(state.bagResting and not state.bagActive and state.bagStacks==0)")
test('Food XP is not part of the camp reminder',setup+"B.db.campAnywhere=true; B.db.campTrackBenefits=false; B.db.campTrackBag=false; campAura(1248406,1000,1800); B:UpdateCamping(); assert(not B.campReminderIcon and B.db.campTrackFood==nil)")
test('Sleeping bag tray row uses the verified item spell away from camp',bagsetup+"bags[211527]=1; items[211527]={name='Cozy Sleeping Bag',spell=429961,usable=true}; slotItem=211527; B:ToggleCampTray(); local row=B.campTray.rows[1]; assert(row.choice.data.item==211527); row.scripts.PreClick(row,'LeftButton',false); assert(row.attrs.type1=='item' and row.attrs.item=='0 1')")
test('Sleeping bag has no crafting fallback',bagsetup+"bags[211527]=1; items[211527]={name='Cozy Sleeping Bag',spell=429961,usable=true}; slotItem=211527; B:ToggleCampTray(); local row=B.campTray.rows[1]; slotItem=nil; bags[211527]=0; local crafts=0; B.CraftCampEntry=function() crafts=crafts+1 end; row.scripts.PreClick(row,'LeftButton',false); row.scripts.PostClick(row,'LeftButton',false); assert(not row.attrs.type1 and crafts==0)")
test('Sleeping bag cooldown prevents another use',bagsetup+"bags[211527]=1; items[211527]={name='Cozy Sleeping Bag',spell=429961,usable=true}; slotItem=211527; B:ToggleCampTray(); local row=B.campTray.rows[1]; C_Container.GetContainerItemCooldown=function() return now,3600,1 end; row.scripts.PreClick(row,'LeftButton',false); assert(not row.attrs.type1)")
test('Sleeping bag does not enter the normal buff action or binding',bagsetup+"local id=B.action.id; bags[211527]=1; items[211527]={name='Cozy Sleeping Bag',spell=429961,usable=true}; B:ToggleCampTray(); assert(B.action.id==id and bindings.MOUSEWHEELDOWN)")
test('Sleeping bag and camp tracking preferences copy in profiles',setup+"B.db.campTrackBenefits=false; B.db.campTrackBag=true; B.db.campAnywhere=false; B:CreateSettingsProfile('XP preference',true); assert(not B.db.campTrackBenefits and B.db.campTrackBag and not B.db.campAnywhere)")
test('Soft glow white is desaturated before neutral RGB tint',"local B=BuffTap; local desaturated,r,g,b; B.button.glow.SetDesaturated=function(_,v) desaturated=v end; B.button.glow.SetVertexColor=function(_,x,y,z) r=x; g=y; b=z end; B.db.effectStyle='soft'; B.db.effectColor='white'; B:ApplyIconEffect(B.button,true); assert(desaturated and r==1 and g==1 and b==1)")
test('Soft glow cyan keeps its blue channel instead of tinting yellow',"local B=BuffTap; local desaturated,r,g,b; B.button.glow.SetDesaturated=function(_,v) desaturated=v end; B.button.glow.SetVertexColor=function(_,x,y,z) r=x; g=y; b=z end; B.db.effectStyle='soft'; B.db.effectColor='cyan'; B:ApplyIconEffect(B.button,true); assert(desaturated and r==.3 and g==.85 and b==1)")
test('Pulse uses the same neutralized texture color path',"local B=BuffTap; local desaturated; B.button.glow.SetDesaturated=function(_,v) desaturated=v end; B.db.effectStyle='pulse'; B.db.effectColor='white'; B:ApplyIconEffect(B.button,true); assert(desaturated)")


test('Camping has its own tab before Weapons without changing window size',"local B=BuffTap; B:Options(); local f=B.options; assert(#f.tabs==14 and f.tabs[6].text=='Camping' and f.tabs[7].text=='Weapons' and f.tabs[11].text=='Diagnostics'); B:ShowCampingOptions(); assert(f.activeTab==6 and f.campingPage.shown)")
test('Camp appearance values cannot change regular reminder appearance',"local B=BuffTap; B:Options(); local size,opacity,style=B.db.size,B.db.opacity,B:IconEffectStyle(); B.options.campingSize:SetValue(72); B.options.campingOpacity:SetValue(50); assert(B.db.campSize==72 and B.db.campOpacity==.5 and B.db.size==size and B.db.opacity==opacity and B:IconEffectStyle()==style)")
test('Camp appearance is copied in named profiles independently',"local B=BuffTap; B.db.campSize=72; B.db.campOpacity=.5; B.db.campEffectStyle='pixel'; B.db.campEffectColor='cyan'; B.db.campEffectSpeed='fast'; B:CreateSettingsProfile('Camp appearance',true); assert(B.db.campSize==72 and B.db.campOpacity==.5 and B.db.campEffectStyle=='pixel' and B.db.campEffectColor=='cyan' and B.db.campEffectSpeed=='fast')")
