test('Camp and buff effects use independent colors and style choices',"local B=BuffTap; B.db.effectStyle='none'; B.db.campEffectStyle='soft'; B.db.campEffectColor='cyan'; B:PreviewCampReminder(); B:UpdatePulse(); assert(B.campReminderIcon.glow.shown and not B.button.glow.shown)")
test('Camp page switches stop its status timer when otherwise idle',"local B=BuffTap; B:ShowCampingOptions(); assert(B.timers.camp); B.options.selectTab(1); assert(not B.timers.camp)")
test('Camp preview and snooze never change ordinary buff bindings',"local B=BuffTap; local binding=bindings.MOUSEWHEELDOWN; B:PreviewCampReminder(); B:SnoozeCamping(600); assert(not B.campReminderIcon.shown and bindings.MOUSEWHEELDOWN==binding)")
test('Camp preview is cancelled when switching profiles',"local B=BuffTap; B:PreviewCampReminder(); B:CreateSettingsProfile('No preview',true); assert(B.campPreviewUntil==nil and not B.campReminderIcon.shown)")
test('Camp settings expose no duplicate food-tracking control',"local B=BuffTap; B:ShowCampingOptions(); assert(B.options.sleepingTrack and B.options.campingTrack and not B.options.campingFood)")
test('Camp tray is compact after moving settings into its own tab',bagsetup+"local make=CreateFrame; CreateFrame=function(...) local f=make(...); f.SetHeight=function(self,h) self.height=h end; return f end; B:ToggleCampTray(); assert(B.campTray.height<=240 and not B.campTray.remind and not B.campTray.trackBag)")
test('Camp style preview respects opacity and size',"local B=BuffTap; B.db.campSize=80; B.db.campOpacity=.4; B:CreateCampReminder(); local icon=B.campReminderIcon; icon.SetSize=function(self,w,h) self.w=w; self.h=h end; icon.SetAlpha=function(self,v) self.alpha=v end; B:PreviewCampReminder(); assert(icon.w==80 and icon.h==80 and icon.alpha==.4)")
test('Camp reminder appearance corruption is bounded',"local B=BuffTap; B.db.campSize=9999; B.db.campOpacity=-20; B.db.campEffectStyle='bad'; B:NormalizeCamping(); assert(B.db.campSize==96 and B.db.campOpacity==.25 and B.db.campEffectStyle=='soft')")


test('Camp label shows acquisition countdown and bag stacks together',setup+"B.db.campTrackBag=true; campAura(1289723,45,60); campAura(429959,7199,7200); playerAuras[429959].applications=2; local text=B:CampLabelText(B:CampingState(),false); assert(text:find('45s',1,true) and text:find('2/3',1,true) and text:find('1h 59m',1,true) and text:find('\\n'))")
test('Camp label shows both tracked benefit timers',setup+"B.db.campTrackBag=true; campAura(1229741,200,3600); campAura(429959,1000,7200); playerAuras[429959].applications=3; local text=B:CampLabelText(B:CampingState(),false); assert(text:find('3m 20s',1,true) and text:find('3/3',1,true) and text:find('16m 40s',1,true))")
test('Camp label countdown and stack visibility are independent',setup+"B.db.campTrackBenefits=false; B.db.campTrackBag=true; campAura(429959,100,7200); playerAuras[429959].applications=2; B.db.campShowCountdown=false; local text=B:CampLabelText(B:CampingState(),false); assert(text=='Bag: 2/3'); B.db.campShowCountdown=true; B.db.campShowStacks=false; text=B:CampLabelText(B:CampingState(),false); assert(text=='Bag: 1m 40s'); B.db.campShowCountdown=false; assert(B:CampLabelText(B:CampingState(),false)=='')")
test('Camp label anchors to the icon midpoint at every size',setup+"B:CreateCampReminder(); local icon=B.campReminderIcon; local point,align,wrap; icon.time.SetPoint=function(_,...) point={...} end; icon.time.SetJustifyH=function(_,v) align=v end; icon.time.SetWordWrap=function(_,v) wrap=v end; for _,size in ipairs({24,40,96}) do B.db.campSize=size; icon.campLabelStyle=nil; B:StyleCampLabel(icon); assert(point[1]=='TOP' and point[2]==icon and point[3]=='BOTTOM' and point[4]==0 and point[5]==-4 and align=='CENTER' and wrap==true) end")
test('Camp text styling is independent from regular reminder text',"local B=BuffTap; B.db.labelFont='default'; B.db.labelColor='green'; B.db.labelSize=10; B.db.campTextFont='names'; B.db.campTextColor='red'; B.db.campTextSize=18; B.db.campTextOutline='thick'; UNIT_NAME_FONT='names.ttf'; B:CreateCampReminder(); local path,size,flags,r; B.campReminderIcon.time.GetFont=function() return 'base.ttf',11,'' end; B.campReminderIcon.time.SetFont=function(_,p,s,f) path=p; size=s; flags=f end; B.campReminderIcon.time.SetTextColor=function(_,v) r=v end; B.campReminderIcon.campLabelStyle=nil; B:StyleCampLabel(B.campReminderIcon); assert(path=='names.ttf' and size==18 and flags=='THICKOUTLINE' and r==1 and B.db.labelColor=='green' and B.db.labelSize==10)")
test('Regular text size outline and spacing apply to the real icon',"local B=BuffTap; local size,flags,top,bottom; B.button.nameLabel.GetFont=function() return 'font.ttf',11,'' end; B.button.nameLabel.SetFont=function(_,_,s,f) size=s; flags=f end; B.button.nameLabel.SetPoint=function(_,...) top={...} end; B.button.label.SetPoint=function(_,...) bottom={...} end; B.db.labelSize=16; B.db.labelOutline='outline'; B.db.labelGap=9; B:ApplyReminderStyle(B.button); assert(size==16 and flags=='OUTLINE' and top[5]==9 and bottom[5]==-9)")
test('Text styles copy through named profiles independently',"local B=BuffTap; B.db.labelSize=14; B.db.labelOutline='thick'; B.db.labelGap=7; B.db.campTextSize=18; B.db.campTextColor='cyan'; B.db.campTextOutline='none'; B.db.campTextGap=10; B.db.campShowCountdown=false; B:CreateSettingsProfile('Text copy',true); assert(B.db.labelSize==14 and B.db.labelOutline=='thick' and B.db.labelGap==7 and B.db.campTextSize==18 and B.db.campTextColor=='cyan' and B.db.campTextOutline=='none' and B.db.campTextGap==10 and not B.db.campShowCountdown)")
test('Camp label ticks without rescanning auras',setup+"B.db.campAnywhere=true; B.db.campTrackBenefits=false; B.db.campTrackBag=true; campAura(429959,45,7200); playerAuras[429959].applications=3; local n=0; local read=C_UnitAuras.GetPlayerAuraBySpellID; C_UnitAuras.GetPlayerAuraBySpellID=function(id) n=n+1; return read(id) end; B:UpdateCamping(); local calls=n; advance(2); assert(n==calls and B.campReminderIcon.time.text:find('43s',1,true)); B:SnoozeCamping(600); assert(not B.timers['camp-text'])")
test('Camp label preview demonstrates stacks and countdown together',"local B=BuffTap; B:PreviewCampReminder(); local text=B.campReminderIcon.time.text; assert(text:find('45s',1,true) and text:find('2/3',1,true))")
test('Camp checkbox grid has consistent left and right columns',"local create=CreateFrame; CreateFrame=function(...) local f=create(...); f.SetPoint=function(self,...) self.point={...} end; return f end; BuffTap:ShowCampingOptions(); local f=BuffTap.options; -- 1.18 cards: 26 px inset left column, 374 right column; label toggles live in the reminder editor (26/208).\nfor _,pair in ipairs({{f.campingTrack,f.sleepingTrack},{f.campingSound,f.campingAnywhere}}) do assert(pair[1].point[2]==26 and pair[2].point[2]==374 and pair[1].point[3]==pair[2].point[3]) end; assert(f.campingCountdown.point[2]==26 and f.campingStacks.point[2]==208 and f.campingCountdown.point[3]==f.campingStacks.point[3])")
test('Camp and regular text controls fit inside the unchanged options panel',"local create=CreateFrame; CreateFrame=function(...) local f=create(...); f.SetPoint=function(self,...) self.point={...} end; f.SetSize=function(self,w,h) self.w=w; self.h=h end; return f end; BuffTap:Options(); local f=BuffTap.options; for _,c in ipairs({f.campingTextFont,f.campingTextSize,f.campingTextColor,f.campingTextOutline,f.campingTextGap,f.fontButton,f.labelSizeButton,f.colorButton,f.labelOutlineButton,f.labelGap,f.reminderSoundButton,f.supplySoundButton}) do assert(c.point[2]+c.w<=704 and -c.point[3]+c.h<=624) end")
test('Main reset look restores text defaults without changing camp text',"local B=BuffTap; B.db.labelSize=18; B.db.labelGap=10; B.db.labelOutline='thick'; B.db.campTextSize=16; B:Options(); local r=B.options.resetLookButton; r.scripts.OnClick(r); assert(B.db.labelSize==18,'first click only arms'); r.scripts.OnClick(r); assert(B.db.labelSize==0 and B.db.labelGap==5 and B.db.labelOutline=='none' and B.db.campTextSize==16)")
test('Malformed text preferences normalize without changing buff choices',"local B=BuffTap; local motw=B.db.buffs.motw; B.db.labelSize=0/0; B.db.labelGap=-99; B.db.campTextSize=999; B.db.campTextGap=math.huge; B:InitDB(); assert(B.db.labelSize==0 and B.db.labelGap==0 and B.db.campTextSize==20 and B.db.campTextGap==4 and B.db.buffs.motw==motw)")


test('Text outline menu has no duplicate inherited default choice',"local choices=BuffTap:TextOutlineChoices(); assert(#choices==3); local seen={}; for _,v in ipairs(choices) do assert(v.key~='default' and not seen[v.key]); seen[v.key]=true end; assert(seen.none and seen.outline and seen.thick)")
test('Game font choice names the actual face when available',"GameFontHighlightSmall={GetFont=function() return 'Fonts\\\\FRIZQT__.TTF',10,'' end}; assert(BuffTap:GameFontLabel()=='Game font: Friz Quadrata')")
test('Game size choice reports the actual point size without rounding it',"GameFontHighlightSmall={GetFont=function() return 'game.ttf',10.5,'' end}; assert(BuffTap:TextSizeLabel(0)=='Game: 10.5 px' and BuffTap:TextSizeLabel(16)=='16 px')")
test('Selecting game font and size resets prior font-string overrides',"local B=BuffTap; GameFontHighlightSmall={GetFont=function() return 'game.ttf',10,'' end}; local fs=B.button.nameLabel; local path,size,flags; fs.GetFont=function() return 'custom.ttf',20,'THICKOUTLINE' end; fs.SetFont=function(_,p,s,f) path=p; size=s; flags=f end; B:ApplyLabelStyle(fs,{labelFont='default',labelSize=0,labelOutline='none',labelColor='white'},'GameFontHighlightSmall'); assert(path=='game.ttf' and size==10 and flags=='')")
test('Legacy main outline resolves to the actual game setting',"local B=BuffTap; GameFontHighlightSmall={GetFont=function() return 'game.ttf',10,'OUTLINE' end}; B.db.labelOutline='default'; B:InitDB(); assert(B.db.labelOutline=='outline'); GameFontHighlightSmall.GetFont=function() return 'game.ttf',10,'' end; B.db.labelOutline='default'; B:InitDB(); assert(B.db.labelOutline=='none')")
test('Legacy camp default outline resolves without retaining a dead choice',"local B=BuffTap; GameFontHighlightSmall={GetFont=function() return 'game.ttf',10,'' end}; B.db.campTextOutline='default'; B:NormalizeCamping(); assert(B.db.campTextOutline=='none')")
test('Camp default color becomes the single white option',"local B=BuffTap; B.db.campTextColor='default'; B:NormalizeCamping(); assert(B.db.campTextColor=='white'); local whites=0; for _,v in ipairs(B:ReminderColors(true)) do assert(v.key~='default'); if v.key=='white' then whites=whites+1 end end; assert(whites==1)")
test('Main inherited colors describe the white and gold distinction',"local choices=BuffTap:ReminderColors(); assert(choices[1].key=='default' and choices[1].name=='Text: white + gold count')")
test('Duplicate font files are normalized and omitted from the menu',"local B=BuffTap; GameFontHighlightSmall={GetFont=function() return 'Fonts/FRIZQT__.TTF',10,'' end}; UNIT_NAME_FONT='fonts\\\\frizqt__.ttf'; DAMAGE_TEXT_FONT='Fonts/SKURRI.TTF'; B.db.labelFont='names'; B.db.campTextFont='names'; B:InitDB(); assert(B.db.labelFont=='default' and B.db.campTextFont=='default'); local choices=B:ReminderFonts(); assert(#choices==2 and choices[1].key=='default' and choices[2].key=='numbers')")
